#include <iostream>
#include <vector>
#include <string>

using namespace std;

struct FastSet {
    int mask;
    vector<uint64_t> table;

    FastSet(int power_of_two) {
        int size = 1 << power_of_two;
        mask = size - 1;
        table.assign(size, 0);
    }

    void insert(uint64_t val) {
        int idx = (val * 11400714819323198485ULL) & mask;
        while (table[idx] != 0 && table[idx] != val) {
            idx = (idx + 1) & mask;
        }
        table[idx] = val;
    }

    bool contains(uint64_t val) const {
        int idx = (val * 11400714819323198485ULL) & mask;
        while (table[idx] != 0) {
            if (table[idx] == val) return true;
            idx = (idx + 1) & mask;
        }
        return false;
    }
};

uint64_t encode(const string& s, int l, int r) {
    uint64_t val = 1;
    for (int i = l; i < r; ++i) {
        val = (val << 5) | (s[i] - 'a' + 1);
    }
    return val;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    FastSet prefixes(18);    // 2^18 = 262,144 entries
    FastSet suffixes(18);    // 2^18 = 262,144 entries
    FastSet substrings(21);  // 2^21 = 2,097,152 entries

    for (int k = 1; k <= n; ++k) {
        string s;
        cin >> s;
        int len = s.size();

        if (k > 1) {
            bool invalid = false;

            // Check if s is an exact substring of some previous string
            if (substrings.contains(encode(s, 0, len))) {
                invalid = true;
            }

            // Check if s can be split into a suffix of S_a and a prefix of S_b
            if (!invalid) {
                for (int i = 1; i < len; ++i) {
                    uint64_t left_val = encode(s, 0, i);
                    uint64_t right_val = encode(s, i, len);
                    if (suffixes.contains(left_val) && prefixes.contains(right_val)) {
                        invalid = true;
                        break;
                    }
                }
            }

            if (invalid) {
                cout << s << "\n";
                return 0;
            }
        }

        // Add all prefixes
        for (int i = 1; i <= len; ++i) {
            prefixes.insert(encode(s, 0, i));
        }

        // Add all suffixes
        for (int i = 0; i < len; ++i) {
            suffixes.insert(encode(s, i, len));
        }

        // Add all substrings
        for (int i = 0; i < len; ++i) {
            for (int j = i + 1; j <= len; ++j) {
                substrings.insert(encode(s, i, j));
            }
        }
    }

    cout << "ok\n";
    return 0;
}
